select table_schema,table_name,column_name,data_type from information_schema.columns where (table_schema='private' and table_name='jra_model_transition_snapshots') or (table_schema='public' and table_name in ('jra_live_rank_snapshots','jra_live_rank_snapshot_entries','jra_live_diagnosis_snapshots','jra_prediction_worker_runs','jra_lab_runs','jra_lab_races','jra_live_runners')) order by table_schema,table_name,ordinal_position limit 200;
